'use client';
import Link from 'next/link';
import { usePathname } from 'next/navigation';

const tabs = [
  { name: 'Overview', href: '/finance' },
  { name: 'Investments', href: '/finance/investments' },
  { name: 'Debt', href: '/finance/debt' },
  { name: 'Tracker', href: '/finance/tracker' },
  { name: 'Learning', href: '/finance/learning' },
];

const Layout = () => {
  const pathname = usePathname();

  return (
    <nav className="flex items-center justify-between bg-carbon-light p-4">
      <span className="status-dot bg-racing-red"></span>
      <h1 className="text-white">FINANCE OS</h1>
      <ul className="flex space-x-4">
        {tabs.map(tab => (
          <li key={tab.href}>
            <Link href={tab.href} className={`text-gray-400 hover:text-white hover:bg-carbon-light ${pathname === tab.href ? 'bg-racing-red text-white shadow-neon-red' : ''}`}>
              {tab.name}
            </Link>
          </li>
        ))}
      </ul>
      <Link href="/finance/settings" className="text-gray-400 hover:text-white hover:bg-carbon-light">Settings</Link>
    </nav>
  );
};

export default Layout;
